    const c = this.chars[this.i]
    this.i++
    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = this.col + (4 - ((this.col - 1) % 4))
    } else {
      this.col++
    }
    return c
  }

  skipTrivia() {
    while (!this.eof()) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        while (!this.eof() && this.peek() !== '\n') this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        const bl = this.line
        const bc = this.col
        this.advance()
        this.advance()
        let depth = 1
        while (depth > 0) {
          if (this.eof()) throw new LexError(bl, bc, 'unterminated block comment')
