          if (cc === '/' && this.peek(1) === '*') {
            this.advance()
            this.advance()
            depth++
            continue
          }
          if (cc === '*' && this.peek(1) === '/') {
            this.advance()
            this.advance()
            depth--
            continue
          }
          this.advance()
        }
        continue
      }
      break
    }
