          const h2 = this.peek(1)
          if (!isHexDigit(h1) || !isHexDigit(h2)) throw new LexError(bl, bc, 'invalid escape \\x')
          this.advance()
          this.advance()
          value += String.fromCharCode(parseInt(h1 + h2, 16))
        } else if (e === 'u') {
          this.advance()
          if (this.peek() !== '{') throw new LexError(bl, bc, 'invalid escape \\u')
          this.advance()
          let hex = ''
          while (!this.eof() && isHexDigit(this.peek())) hex += this.advance()
          if (hex.length === 0) throw new LexError(bl, bc, 'invalid escape \\u')
          if (this.eof() || this.peek() !== '}') throw new LexError(bl, bc, 'invalid escape \\u')
          this.advance()
          const code = parseInt(hex, 16)
          if (code > 0x10ffff) throw new LexError(bl, bc, 'invalid escape \\u')
          value += String.fromCodePoint(code)
        } else {
          throw new LexError(bl, bc, `invalid escape \\${e}`)
        }
        continue
      }
      value += c
      this.advance()
    }
    return { line, col, kind: 'string', text: value }
  }

  rawStringToken() {
    const line = this.line
    const col = this.col
    this.advance() // r
    this.advance() // opening quote
    let value = ''
    while (true) {
      if (this.eof()) throw new LexError(line, col, 'unterminated string')
