    const line = this.line
    const col = this.col
    const c = this.peek()
    const next = this.peek(1)
    const two = next === undefined ? c : c + next
    if (TWO_CHAR_PUNCT.has(two)) {
      this.advance()
      this.advance()
      return { line, col, kind: 'punct', text: two }
    }
    if (ONE_CHAR_PUNCT.has(c)) {
      this.advance()
      return { line, col, kind: 'punct', text: c }
    }
    throw new LexError(line, col, `unexpected character ${c}`)
  }
